INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('004ac1ab-1609-45b5-8ea5-ed285d5b7eac', '21feff02-016d-46e2-bb9d-c27495133b1b', '41. óra: Összetett műveletek, zárójelfelbontás', 'Műveleti sorrend, zárójelezés szabályai tizedes és közönséges törtekkel.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "5ce39712-4148-4800-a41a-5d8189fcca22", "text": "Mi a helyes műveleti sorrend?", "type": "multiple-choice", "options": [{"id": "2c8d85c0-eb1f-48a2-88a1-bd5876ed8f31", "text": "Zárójelben lévő műveletek -> szorzás/osztás balról jobbra -> összeadás/kivonás balról jobbra", "isCorrect": true}, {"id": "3b77f6a6-107a-412e-b112-9d1d856bd38f", "text": "Mindig összeadással kezdünk", "isCorrect": false}, {"id": "db664e75-2757-4d3c-bdac-92995a069de2", "text": "Balról jobbra haladunk művelet típustól függetlenül", "isCorrect": false}, {"id": "b1daeb40-1614-4bc9-ab9d-877aebfb5893", "text": "Kivonással kezdünk", "isCorrect": false}], "timeLimit": 15}, {"id": "2b9479d2-d53c-47ae-871f-b6ceabc8988c", "text": "Mennyi 2 + 3 * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "8a6d948b-7a2c-4545-8925-b47df92470f7", "text": "Mennyi (2 + 3) * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "d8054fc5-094a-4cba-b51d-c8adbd1b8588", "text": "Mennyi 10 - 2 * 3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "9ed09d73-32ab-4e8e-973d-b2fbd40d1683", "text": "A zárójel megváltoztatja a műveletek elvégzésének megszokott sorrendjét.", "type": "true-false", "options": [{"id": "29856635-e733-4ab6-b2ef-b81f7f9b50bc", "text": "Igaz", "isCorrect": true}, {"id": "c733e3df-9127-4253-895c-778f48fde76e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "12c6cb71-91c6-4d7f-bf48-01f10b6db02a", "text": "Mennyi 0,5 + 0,5 * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2.5"}, {"id": "dc8a35af-0ab2-43e2-a90d-069c1f1cbd0c", "text": "Mennyi (0,5 + 0,5) * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e069d0b8-36ca-41f1-b832-ad39d13b1246', '21feff02-016d-46e2-bb9d-c27495133b1b', '42. óra: Összetett műveletek, zárójelfelbontás gyakorlása', 'Gyakorlás feladatlapok és összetett kifejezések segítségével.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "3b84c25d-34e7-435d-9c2f-8acdf4086fc3", "text": "Mennyi 100 - (20 + 30)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "e462a8dd-ccdc-4b96-bbc0-9a680b4b01bc", "text": "Mennyi 15 : 3 + 2 * 5? (5 + 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "3c021255-6ec2-4eab-9606-9cbfd8e454e4", "text": "Mennyi 0,2 * 5 + 0,8 : 2? (1 + 0,4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1.4"}, {"id": "d0f3e96f-ceac-46b1-8a70-b27f68990395", "text": "A szorzás és az osztás egyenrangú műveletek, elvégzésük balról jobbra haladva történik.", "type": "true-false", "options": [{"id": "78829875-38d8-4c9e-9465-1deaf3dec908", "text": "Igaz", "isCorrect": true}, {"id": "88fb3139-9472-4db2-93e9-23c1113207f5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c2cf29d6-886c-469d-b9fa-9c8ebf7259a5", "text": "Mennyi (1,2 + 0,8) * (3,5 - 1,5)? (2 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "9fe5ab9c-9077-4a15-8b16-e0fdaabcf7dd", "text": "Ha a zárójel előtt minusz jel áll, a zárójel elhagyásakor a bent lévő tagok előjele az ellenkezőjére vált.", "type": "true-false", "options": [{"id": "c9221dd1-5f81-4630-ae13-57154e76a8d3", "text": "Igaz", "isCorrect": true}, {"id": "3f852437-06d7-40d7-8033-6b12a1b3d730", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b0d02e50-3cfc-4043-b7e4-3779c038af4a", "text": "Mennyi 50 - 5 * 8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('a3a5e336-1a3d-499b-adad-1940e9c5e115', '21feff02-016d-46e2-bb9d-c27495133b1b', '43. óra: Összefoglalás', 'A törtekről tanultak ismétlése, rendszerezése, algoritmusos gondolkodás.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "9a2af568-f1a0-4da6-a226-0967dd956295", "text": "Mennyi 3/4 * 4/5?", "type": "multiple-choice", "options": [{"id": "28e686dd-c176-4248-9b82-c27af51a6ce0", "text": "3/5", "isCorrect": true}, {"id": "7d060fd2-fe81-4500-8866-e17f37b59026", "text": "12/20", "isCorrect": false}, {"id": "509723ac-445a-4929-abe7-806886a2c244", "text": "7/9", "isCorrect": false}, {"id": "f97a7c15-fa07-461c-bde2-99b3cd56b184", "text": "4/5", "isCorrect": false}], "timeLimit": 15}, {"id": "c62b5f99-d0cd-436a-8183-08323cf1e334", "text": "Mennyi 1/2 : 1/3? (1/2 * 3/1)", "type": "multiple-choice", "options": [{"id": "43e099c8-122e-4c59-9d56-5227aa1a048e", "text": "3/2 (1,5)", "isCorrect": true}, {"id": "386af59d-ca23-487b-988c-9b87a4c9f980", "text": "1/6", "isCorrect": false}, {"id": "00cc9a49-f42a-416c-b9de-8a935b7da5c8", "text": "2/3", "isCorrect": false}, {"id": "f1048889-4d7a-4e39-82cc-7462f3f302a2", "text": "1/5", "isCorrect": false}], "timeLimit": 15}, {"id": "b1d8d944-09d3-4514-b6d1-8174188b6b31", "text": "Mennyi 2,5 * 0,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "1f60b68e-b67e-492e-8eb7-20c543695b6e", "text": "Mennyi 6,4 : 0,8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "e8e2f187-6f0b-4de7-95a7-3ed2e5afe4ea", "text": "A 0,75 megegyezik a 3/4 közönséges tört értékével.", "type": "true-false", "options": [{"id": "072bdc69-a587-4709-88b2-10d2ae006008", "text": "Igaz", "isCorrect": true}, {"id": "8cfed094-72fb-4076-a42c-b967f2a29398", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c403f5a8-9182-41a9-baa1-ab56a5455512", "text": "Mennyi 50-nek a 40%-a (vagy 2/5 része)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "d92d59f6-f09d-4bfe-abb6-d3f576366cd7", "text": "Melyik szám reciproka 0,5 (azaz 1/2)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('42857095-1fb1-4635-a724-ad6d917a7879', '21feff02-016d-46e2-bb9d-c27495133b1b', '44. óra: Feladatmegoldás', 'Gyakorló feladatok megbeszélése egyéni és csoportmunkában.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "5680f526-0949-4f01-9206-332d38db6290", "text": "Mennyi 0,75 + 1/4? (0,75 + 0,25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "abc468ef-bb20-4a16-a22b-79229a9ceb48", "text": "Mennyi 1,5 - 3/4? (1,5 - 0,75)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.75"}, {"id": "2bb2e6e5-cdc9-4a53-ad55-b6f69effeda0", "text": "Peti elköltötte a pénze 2/5-ét, majd a maradék 1/2-ét. A pénze hányadrésze maradt meg?", "type": "multiple-choice", "options": [{"id": "d9a6ccbc-ea54-4f38-ac44-044b9344bac2", "text": "3/10 (azaz 30%-a)", "isCorrect": true}, {"id": "0aa9333f-e0ab-48c7-8ffe-4fb206a44455", "text": "1/5", "isCorrect": false}, {"id": "828b3136-d27d-420e-b414-14238e332973", "text": "1/2", "isCorrect": false}, {"id": "a6df6ff9-1ec0-4953-b8c9-87a7e730c7c3", "text": "0", "isCorrect": false}], "timeLimit": 15}, {"id": "c8331138-1ad6-4418-bf72-00642c43bb53", "text": "Ha a számláló és a nevező megegyezik, a tört értéke 1.", "type": "true-false", "options": [{"id": "b8b025d8-e512-438f-a910-e50e52c43127", "text": "Igaz", "isCorrect": true}, {"id": "d463ca91-41c9-494b-a183-691577ace95e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "79cf0cef-352e-4042-acec-8f68a027e4e1", "text": "Mennyi 0,8 * 2,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "44b253b8-433b-49f0-b284-0b4d8586a4e6", "text": "Mennyi 9 : 0,3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "ae2ec158-c20e-49b2-ba96-838a263e371a", "text": "A 0,125 megegyezik az 1/8 tört értékével.", "type": "true-false", "options": [{"id": "73470f97-0abb-4399-848a-0920de86af7f", "text": "Igaz", "isCorrect": true}, {"id": "9a5ede32-3462-4fca-ac8c-bfae5e9da732", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c8ec5bfe-6d97-4a8c-bdf1-d76ec042a8db', '21feff02-016d-46e2-bb9d-c27495133b1b', '45. óra: Játékos feladatok törtekkel', 'Társasjáték törtekkel, folyamatos tanári ellenőrzés és hibajavítás.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "167a9656-4a35-43df-923a-d98d520a2b5e", "text": "Melyik tört azonos értékű 4/12-vel?", "type": "multiple-choice", "options": [{"id": "910bf192-e45c-4890-8373-a1480ae72a90", "text": "1/3", "isCorrect": true}, {"id": "f4269c20-2c34-476c-8804-3a7222ee8a9b", "text": "1/4", "isCorrect": false}, {"id": "8c633636-865b-4e66-8b68-60c8e912df33", "text": "2/3", "isCorrect": false}, {"id": "95dadb54-3d90-4296-9eae-111ed57622bd", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "4a749044-06af-489a-883c-f744de6c76b2", "text": "Melyik tört azonos értékű 5/20-szal?", "type": "multiple-choice", "options": [{"id": "3bdd4815-a9ab-4a4c-82b7-19636912477b", "text": "1/4", "isCorrect": true}, {"id": "e33c07f2-b248-4e9f-ae2c-6a32fb60553f", "text": "1/5", "isCorrect": false}, {"id": "fe022512-a255-439f-aa8e-26210df1db31", "text": "2/5", "isCorrect": false}, {"id": "3437a2d9-c9b1-45a0-af45-6b2d4beded63", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "9d770d29-0861-4e32-9969-1bb8c2aea099", "text": "Mennyi 0,6 * 0,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.3"}, {"id": "0564a20c-2261-48c5-9627-4c3bfaeeafaf", "text": "Mennyi 0,4 : 0,2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "404e5973-a1bd-4a74-88d2-63505029daec", "text": "A 0,5 nagyobb, mint a 0,45.", "type": "true-false", "options": [{"id": "9bcaf54b-72fe-4d7e-99f1-57bcf1abc632", "text": "Igaz (0,50 > 0,45)", "isCorrect": true}, {"id": "cdbcfc69-5d76-458f-9af2-c1d97effd087", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "17962371-9424-4a90-8137-d9ed65ce6753", "text": "Hány század van 0,3-ban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "3aaee10d-89db-40ab-8cc6-d70f8a6f3ce6", "text": "A törtek átírása tizedes tört alakba megkönnyíti az összehasonlítást.", "type": "true-false", "options": [{"id": "36620712-b5b7-46a9-96a3-e70bf3bf8129", "text": "Igaz", "isCorrect": true}, {"id": "04e1653c-72f4-4617-8d6c-5c208c7c493f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('2b8cb294-9c28-4d64-b87f-95d10c9afab6', '21feff02-016d-46e2-bb9d-c27495133b1b', '46. óra: Témazáró dolgozat', 'Témazáró számonkérés a Törtek fejezetből (10 kérdés).', 'Matematika', '6. osztály', 'Törtek', '[{"id": "b7ab5e92-61a0-4944-acb6-dc2976f347da", "text": "1. Mennyi 2/3 + 1/6? (4/6 + 1/6)", "type": "multiple-choice", "options": [{"id": "c871b059-2e99-4019-8819-8d13c105283a", "text": "5/6", "isCorrect": true}, {"id": "6e22a41e-a101-4e6a-9032-0709a1fe867a", "text": "3/9", "isCorrect": false}, {"id": "48b9b896-6356-4c2c-a4a4-6c2c445e4faa", "text": "3/6", "isCorrect": false}, {"id": "5b87d3b2-5572-4e22-846d-16a823f729b5", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "54b40d70-5282-4301-8e81-c66b74fe61ec", "text": "2. Mennyi 3/5 * 5/6?", "type": "multiple-choice", "options": [{"id": "21b5abd1-3879-4c57-b09e-1f463f126035", "text": "15/30 (azaz 1/2)", "isCorrect": true}, {"id": "f7756d88-53ee-4a1c-8311-2072370c769c", "text": "8/11", "isCorrect": false}, {"id": "fa3ab147-93a4-4490-b110-a294dda9fd35", "text": "15/11", "isCorrect": false}, {"id": "a3237e81-6fc6-4f66-8858-caeb8443a4de", "text": "3/6", "isCorrect": false}], "timeLimit": 15}, {"id": "c50b307d-040f-4943-aa66-0039bec59803", "text": "3. Mennyi 3/4 : 1/2? (3/4 * 2/1)", "type": "multiple-choice", "options": [{"id": "79d3ded5-856e-4cc6-9691-18e2e0b1e878", "text": "6/4 (azaz 3/2 vagy 1,5)", "isCorrect": true}, {"id": "818cda03-2417-4a4a-b07e-d07a431f92bc", "text": "3/8", "isCorrect": false}, {"id": "d360e4d3-a5b1-4872-8a70-e67b9bc157f9", "text": "1/4", "isCorrect": false}, {"id": "4e39b614-3006-4dcd-833b-2cd6099f802f", "text": "2/4", "isCorrect": false}], "timeLimit": 15}, {"id": "205c726e-a6d7-475f-813e-afd9cc967a7b", "text": "4. Mi a 4/9 reciproka?", "type": "multiple-choice", "options": [{"id": "c6215903-4ade-4375-8a49-20eeeb968f44", "text": "9/4", "isCorrect": true}, {"id": "a898ec74-e787-4bb4-a69a-18f6359e526e", "text": "-4/9", "isCorrect": false}, {"id": "7fecc4dc-0e15-4e05-939c-3c794cb55ef8", "text": "1/4", "isCorrect": false}, {"id": "7b9db44b-caf0-4c2c-9bff-6be117e6046c", "text": "4/9", "isCorrect": false}], "timeLimit": 15}, {"id": "144155d0-bbe0-488f-96a7-605999948c65", "text": "5. Mennyi 2,4 + 3,8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6.2"}, {"id": "bccefa5f-5920-464c-9a36-54c3fe2a710e", "text": "6. Mennyi 1,5 * 0,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.6"}, {"id": "ba4bd3c6-43a9-4750-a6cd-a7bd65c557c1", "text": "7. Mennyi 4,2 : 0,7?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "b3d52728-46c1-4d2b-8278-4149ffbeae0e", "text": "8. Mennyi 60-nak a 2/3 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "7656b2d3-b69b-430f-a524-c7ac1f640b72", "text": "9. A 0,25 megegyezik az 1/4 törttel.", "type": "true-false", "options": [{"id": "b8de93e4-3d8c-4de1-8679-aeb7b9c75b38", "text": "Igaz", "isCorrect": true}, {"id": "39dfc5bf-96cc-48bc-b6d8-182f2c19e7a2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "93973271-6664-4eed-911e-7d42444a706f", "text": "10. Mennyi (1,5 + 0,5) * 3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c37b49b0-40c4-4fc7-b7e0-ae21be4a7df8', '21feff02-016d-46e2-bb9d-c27495133b1b', '47. óra: Témazáró dolgozat értékelése', 'A dolgozat megbeszélése, a törtek műveleteinek összefoglaló értékelése.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "aa62dff7-519c-4074-885e-bbc9ef0938cf", "text": "Mi a leggyakoribb hiba a törtek osztásakor?", "type": "multiple-choice", "options": [{"id": "62e1943d-bfa1-415e-a6e1-aa51b6357d3a", "text": "Az osztó reciprokával való szorzás elfelejtése", "isCorrect": true}, {"id": "96936507-c223-43ac-8df4-996d3c56eccb", "text": "A számlálók leírása", "isCorrect": false}, {"id": "6a8cd993-c3c8-4988-b136-bf26f09c0a31", "text": "A zárójel használata", "isCorrect": false}, {"id": "2f0a438d-e5b6-469f-bb05-a362ed1705fd", "text": "A művelet elvégzése", "isCorrect": false}], "timeLimit": 15}, {"id": "a88cf353-f29b-4c31-b13e-bfc516114856", "text": "Tizedes törtek osztásakor az osztónak egész számnak kell lennie a művelet elvégzése előtt.", "type": "true-false", "options": [{"id": "1dbe48d1-234c-45b9-824f-0b5847584dac", "text": "Igaz", "isCorrect": true}, {"id": "1e61c0a6-ba8f-4efe-bdb2-c365181034d1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "be5a188c-700c-4a30-9ffd-55e56f1f73da", "text": "Mennyi 1/2 * 4/5?", "type": "multiple-choice", "options": [{"id": "32aa601d-8875-48af-ab7e-089f686b72b7", "text": "2/5", "isCorrect": true}, {"id": "bbfd8349-9d9a-472d-a3d4-d09fff82ae80", "text": "4/10", "isCorrect": false}, {"id": "c501a927-a21f-42b2-8da1-eb3d44a762fe", "text": "1/5", "isCorrect": false}, {"id": "8cb52fa7-99fd-4c93-85a6-abcafec2fd25", "text": "5/7", "isCorrect": false}], "timeLimit": 15}, {"id": "29699990-e32d-4bd4-aa3a-2d104abe6378", "text": "Mennyi 2,5 : 0,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "59ca560a-f0e6-454f-a3c2-d90e75441aaa", "text": "A gyakorlás és a hibák javítása segít a jobb teljesítmény elérésében.", "type": "true-false", "options": [{"id": "1dce35e9-e509-4c11-b88a-ddffaebc233f", "text": "Igaz", "isCorrect": true}, {"id": "91d518a2-9352-445e-9845-138c9d740c5f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6f632c7c-1da9-48db-b43d-e5b5f4fd2078", "text": "Mennyi 100-nak a 3/10 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "8521c8e4-bac1-4838-955c-86a02df408c7", "text": "Mennyi 0,8 + 0,4 - 0,2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('d7e18afe-95e9-44b5-856a-8630a307e334', '21feff02-016d-46e2-bb9d-c27495133b1b', '48. óra: Síkbeli alakzatok', 'Szögek fajtái, háromszögek csoportosítása, belső szögek összege (180°).', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "b5058dbb-572c-42f0-98b4-79fdfdafc3b2", "text": "Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "c668e6b7-c995-42e8-af83-f67e30b3e6ad", "text": "Milyen szög a 90°-nál kisebb pozitív szög?", "type": "multiple-choice", "options": [{"id": "a83fea54-a124-4bcd-bb1e-c32e2363029f", "text": "Hegyesszög", "isCorrect": true}, {"id": "b1ce9740-8994-4cd3-978f-9f2c9d7a3574", "text": "Derékszög", "isCorrect": false}, {"id": "edde376c-ed80-478e-9228-db34172713d4", "text": "Tompaszög", "isCorrect": false}, {"id": "7cbbac06-b406-45f6-879c-dff7972ae50d", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}, {"id": "59f2758b-377b-4fad-83d6-2523c624ba57", "text": "Milyen szög a pontosan 90°-os szög?", "type": "multiple-choice", "options": [{"id": "cb782185-39f0-4846-9b66-608dab71bcfb", "text": "Derékszög", "isCorrect": true}, {"id": "3dfb49e7-98af-47de-9c05-9d6890dc4ae8", "text": "Hegyesszög", "isCorrect": false}, {"id": "eff6f0a9-1602-424c-b504-3adfc9624be2", "text": "Tompaszög", "isCorrect": false}, {"id": "54095493-8c87-4551-a540-95f00745bc22", "text": "Teljes szög", "isCorrect": false}], "timeLimit": 15}, {"id": "314d84bb-745c-41e9-aee6-5865a0f69688", "text": "Milyen szög a 90° és 180° közötti szög?", "type": "multiple-choice", "options": [{"id": "9091286e-43b9-4a19-9afd-e5f7ca8cb3d1", "text": "Tompaszög", "isCorrect": true}, {"id": "607c56d4-62dd-4f69-9205-05ea857b0e4b", "text": "Hegyesszög", "isCorrect": false}, {"id": "dba0cc20-6adf-4168-b96f-265c8987cf0b", "text": "Derékszög", "isCorrect": false}, {"id": "a39b0164-5112-464d-a120-21d21bc2de73", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}, {"id": "7d1a4c36-9777-4a1e-84a0-1c83ec90a103", "text": "Ha a háromszög két szöge 50° és 60°, mennyi a harmadik szög?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "70"}, {"id": "653a03d2-3e89-4bb0-b52b-3a44360b0647", "text": "A derékszögű háromszögnek van egy 90°-os szöge.", "type": "true-false", "options": [{"id": "11cc7004-7a52-4545-b688-93e6db3ab564", "text": "Igaz", "isCorrect": true}, {"id": "0c9d8c40-ca75-4b72-9e43-c0e8fde49cba", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "632fa0cf-3670-45e7-b30d-f932ff3583f3", "text": "A szabályos háromszög (egyenlő oldalú) minden belső szöge 60°-os.", "type": "true-false", "options": [{"id": "05f06a1b-8842-4127-8cea-03ed058f2c58", "text": "Igaz", "isCorrect": true}, {"id": "3c65c5b1-879a-494c-b738-606eca5bacc1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('61509e35-5dc6-44b1-a1d5-652099869b8f', '21feff02-016d-46e2-bb9d-c27495133b1b', '49. óra: Síkbeli alakzatok II.', 'Négyszögek fajtái (téglalap, négyzet, rombusz, paralelogramma, trapéz) és szögösszegük (360°).', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "b0edcdf8-ef72-4442-b871-f23bd7c5c3a2", "text": "Mennyi a konvex négyszögek belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "10ff20f1-be24-4b1b-9716-41d7bec6a164", "text": "Melyik négyszögnek van minden oldala egyenlő hosszú és minden szöge derékszög?", "type": "multiple-choice", "options": [{"id": "c6dfff25-7156-4535-a5c3-3c154007b21a", "text": "Négyzet", "isCorrect": true}, {"id": "c4725d58-43a5-4916-aaf6-f520b9663cf9", "text": "Rombusz", "isCorrect": false}, {"id": "6e1ec2d9-acbb-4ed5-9c20-0e52ca851fe3", "text": "Téglalap", "isCorrect": false}, {"id": "f5e4f0ea-3ba1-4a3c-9c83-e1fda295d048", "text": "Trapéz", "isCorrect": false}], "timeLimit": 15}, {"id": "15465dac-343a-446d-b8a0-dadf57c5eed0", "text": "Melyik négyszögnek van minden oldala egyenlő, de nem feltétlenül derékszögűek a szögei?", "type": "multiple-choice", "options": [{"id": "daa91454-30e6-42ff-9a0c-4c8dce24258a", "text": "Rombusz", "isCorrect": true}, {"id": "f63c23f1-0ca7-4c91-8e72-b3f725356fca", "text": "Téglalap", "isCorrect": false}, {"id": "54d5893f-f7e3-46a0-96fc-d1004a047b62", "text": "Trapéz", "isCorrect": false}, {"id": "652be048-646a-4c0c-8f5f-40cfe285a7e0", "text": "Deltoid", "isCorrect": false}], "timeLimit": 15}, {"id": "5d4f1e5b-2d92-4f67-9dc9-d4d4e56fa277", "text": "A trapéznak van legalább egy pár párhuzamos oldala.", "type": "true-false", "options": [{"id": "003d6aeb-d514-4aa1-adf9-cd8d9b0ec9da", "text": "Igaz", "isCorrect": true}, {"id": "97146296-313e-423b-aadc-5e25f0e2828d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "47824d4c-199e-45ad-8d32-625ad6f29cab", "text": "A paralelogramma szemközti oldalai párhuzamosak és egyenlő hosszúak.", "type": "true-false", "options": [{"id": "a0bf558b-004c-46b0-be84-8ed12bf5e3c3", "text": "Igaz", "isCorrect": true}, {"id": "165b7148-4658-4815-8976-504176cd78f0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "53a90000-5eaa-40a1-b717-a397aa9901f1", "text": "A négyzet egyben rombusz és téglalap is.", "type": "true-false", "options": [{"id": "6f17ab82-c975-4c14-96c3-6f8dbd69d914", "text": "Igaz", "isCorrect": true}, {"id": "5627d49e-bb38-4975-976f-1a2503f5513e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8badadac-b9a3-449d-9993-dfaaf277bdc3", "text": "Hány átlója van egy négyszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('16b67a6a-1916-4f8e-889c-c20aff2ddad4', '21feff02-016d-46e2-bb9d-c27495133b1b', '50. óra: Egybevágóság', 'Egybevágó alakzatok felismerése, fedésbe hozása eltolással, forgatással, tükrözéssel.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "a08c0d14-6ba2-4986-b50e-62980bac541e", "text": "Mikor nevezünk két síkbeli alakzatot egybevágónak?", "type": "multiple-choice", "options": [{"id": "c8375066-2fb2-4a21-86df-e6ef057bb686", "text": "Ha alakjuk és méretük pontosan megegyezik, mozgatással fedésbe hozhatók", "isCorrect": true}, {"id": "4e354f78-d1f1-4573-8c33-7f44851dc912", "text": "Ha csak a színük egyezik", "isCorrect": false}, {"id": "701513df-e7ec-414e-8606-d4017ee1ea58", "text": "Ha a területük 0", "isCorrect": false}, {"id": "28afb48f-5f88-422b-bafb-2073b438510e", "text": "Ha az egyik kétszer akkora", "isCorrect": false}], "timeLimit": 15}, {"id": "12aff72c-f372-4924-b7a3-60a92e91192a", "text": "Két egybevágó alakzat kerülete és területe megegyezik.", "type": "true-false", "options": [{"id": "f6036843-cb30-4128-bf47-ee627df6eb52", "text": "Igaz", "isCorrect": true}, {"id": "41149c11-a3cc-4c40-bfa1-1a0041ecd2aa", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "dd06200e-d090-4139-8d0f-f638a1cc30a7", "text": "Az eltolás, forgatás és tükrözés egybevágósági transzformációk.", "type": "true-false", "options": [{"id": "766f208a-22c2-4ab2-bb54-06ae908df868", "text": "Igaz", "isCorrect": true}, {"id": "5e60e48f-3224-4c0c-96a2-740e93514cea", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f778cbec-c912-4ccc-9b62-cb22f9b9f6b7", "text": "Egy alakzat eltolása során megváltozik-e az alakzat területe?", "type": "true-false", "options": [{"id": "f6948865-2a81-4a9a-948c-9d83859053e0", "text": "Igaz", "isCorrect": false}, {"id": "cfa88186-f728-484a-b831-59759813933c", "text": "Hamis (a terület